// llmconf builds the two llama-swap configs from one file per model.
//
//	platform/llm/models/<name>.yaml   runtime: gpu|cpu, description, ttl, cmd
//	platform/llm/config-gpu.yaml      generated, models with runtime gpu
//	platform/llm/config-cpu.yaml      generated, models with runtime cpu
//
// Usage: llmconf -dir platform/llm [-check]. With -check it writes nothing and
// fails if the generated files are out of date (CI).
package main

import (
	"bytes"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"
)

type model struct {
	Runtime     string `yaml:"runtime"`
	Description string `yaml:"description"`
	TTL         int    `yaml:"ttl"`
	Cmd         string `yaml:"cmd"`
}

type entry struct {
	Description string `yaml:"description"`
	Cmd         string `yaml:"cmd"`
	Proxy       string `yaml:"proxy"`
	TTL         int    `yaml:"ttl"`
}

type config struct {
	HealthCheckTimeout int              `yaml:"healthCheckTimeout"`
	LogRequests        bool             `yaml:"logRequests"`
	Models             map[string]entry `yaml:"models"`
}

const header = "# Generated by services/llmconf from models/*.yaml. Do not edit.\n"

// validate returns the problems with one model definition.
func validate(name string, m model) []string {
	var bad []string
	add := func(f string, a ...any) { bad = append(bad, name+": "+fmt.Sprintf(f, a...)) }
	if strings.ContainsAny(name, " /\\\"'") || name == "" {
		add("name must not contain spaces, slashes or quotes")
	}
	switch m.Runtime {
	case "gpu":
	case "cpu":
		if !strings.Contains(m.Cmd, "-ngl 0 ") && !strings.HasSuffix(m.Cmd, "-ngl 0") &&
			!strings.Contains(m.Cmd, "--n-gpu-layers 0") {
			add("runtime cpu needs -ngl 0 in cmd, or it would try to use a GPU that this gateway does not have")
		}
	default:
		add("runtime must be gpu or cpu, got %q", m.Runtime)
	}
	if m.TTL <= 0 {
		add("ttl must be a positive number of seconds")
	}
	if !strings.Contains(m.Cmd, "--port 9999") {
		add("cmd must listen on --port 9999, the generated proxy points there")
	}
	if !strings.Contains(m.Cmd, "-m /models/") {
		add("cmd must load a file with -m /models/<file>")
	}
	return bad
}

// build returns the generated files, keyed by file name, and any problems.
func build(dir string) (map[string][]byte, []string, error) {
	files, err := filepath.Glob(filepath.Join(dir, "models", "*.yaml"))
	if err != nil {
		return nil, nil, err
	}
	if len(files) == 0 {
		return nil, nil, fmt.Errorf("no model files in %s/models", dir)
	}
	sort.Strings(files)
	cfgs := map[string]*config{
		"gpu": {HealthCheckTimeout: 300, LogRequests: true, Models: map[string]entry{}},
		"cpu": {HealthCheckTimeout: 600, LogRequests: true, Models: map[string]entry{}},
	}
	var bad []string
	for _, f := range files {
		raw, err := os.ReadFile(f)
		if err != nil {
			return nil, nil, err
		}
		var m model
		dec := yaml.NewDecoder(bytes.NewReader(raw))
		dec.KnownFields(true)
		name := strings.TrimSuffix(filepath.Base(f), ".yaml")
		if err := dec.Decode(&m); err != nil {
			bad = append(bad, fmt.Sprintf("%s: %v", name, err))
			continue
		}
		if p := validate(name, m); len(p) > 0 {
			bad = append(bad, p...)
			continue
		}
		cfgs[m.Runtime].Models[name] = entry{
			Description: m.Description,
			Cmd:         strings.Join(strings.Fields(m.Cmd), " "),
			Proxy:       "http://127.0.0.1:9999",
			TTL:         m.TTL,
		}
	}
	out := map[string][]byte{}
	for rt, c := range cfgs {
		b, err := yaml.Marshal(c)
		if err != nil {
			return nil, nil, err
		}
		out["config-"+rt+".yaml"] = append([]byte(header), b...)
	}
	return out, bad, nil
}

func main() {
	dir := flag.String("dir", "platform/llm", "llm directory")
	check := flag.Bool("check", false, "fail if generated files are out of date, write nothing")
	flag.Parse()

	out, bad, err := build(*dir)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	for _, b := range bad {
		fmt.Println(b)
	}
	if len(bad) > 0 {
		os.Exit(1)
	}
	names := make([]string, 0, len(out))
	for n := range out {
		names = append(names, n)
	}
	sort.Strings(names)
	stale := false
	for _, n := range names {
		path := filepath.Join(*dir, n)
		if *check {
			cur, _ := os.ReadFile(path)
			if !bytes.Equal(cur, out[n]) {
				fmt.Printf("%s is out of date, run: go run ./services/llmconf -dir %s\n", path, *dir)
				stale = true
			}
			continue
		}
		if err := os.WriteFile(path, out[n], 0o644); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		fmt.Println("wrote", path)
	}
	if stale {
		os.Exit(1)
	}
}
